SELECT i_category, i_item_id, i_product_name, ca_city AS ship_city, total_profit, sales_cnt, CASE WHEN total_profit > 10000 THEN 'HIGH' WHEN total_profit > 5000 THEN 'MEDIUM' ELSE 'LOW' END AS profit_level, profit_rank FROM ( SELECT i.i_category, i.i_item_id, i.i_product_name, ca.ca_city, SUM(ws.ws_net_profit) AS total_profit, COUNT(*) AS sales_cnt, RANK() OVER (PARTITION BY i.i_category ORDER BY SUM(ws.ws_net_profit) DESC) AS profit_rank FROM web_sales ws JOIN item i ON ws.ws_item_sk = i.i_item_sk JOIN customer_address ca ON ws.ws_ship_addr_sk = ca.ca_address_sk GROUP BY i.i_category, i.i_item_id, i.i_product_name, ca.ca_city ) t WHERE profit_rank <= 5 ORDER BY i_category, profit_rank
